<?php
require_once __DIR__.'/../../config/cors.php'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../helpers/response.php'; require_once __DIR__.'/../../middleware/auth.php';
$actor=requireAuth($pdo); $method=$_SERVER['REQUEST_METHOD']; if($method!=='GET') requireCsrfToken();
if($method==='GET'){ $where=[];$p=[]; if(isset($_GET['id'])){$where[]='d.id=:id';$p['id']=(int)$_GET['id'];} if(isset($_GET['status'])&&$_GET['status']!==''){$where[]='d.status=:status';$p['status']=$_GET['status'];} $q=trim((string)($_GET['search']??'')); if($q!==''){$where[]='(d.name LIKE :q OR d.phone LIKE :q OR d.license_number LIKE :q)';$p['q']='%'.$q.'%';} $sql='SELECT d.id,d.name,d.phone,d.license_number AS licenseNumber,d.status,d.address,d.created_at AS createdAt,d.updated_at AS updatedAt,(SELECT COUNT(*) FROM vehicles v WHERE v.driver_id=d.id) AS vehicleCount FROM drivers d'; if($where)$sql.=' WHERE '.implode(' AND ',$where); $sql.=' ORDER BY d.name,d.id'; $st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll(); foreach($rows as &$r){$r['id']=(string)$r['id'];$r['vehicleCount']=(int)$r['vehicleCount'];} sendResponse(['success'=>true,'data'=>isset($_GET['id'])?($rows[0]??null):$rows]); }
if($actor['role']!=='admin') sendError('Admin access required.',403); $body=json_decode(file_get_contents('php://input'),true)?:[]; $id=isset($_GET['id'])?(int)$_GET['id']:0; $name=trim((string)($body['name']??''));$phone=trim((string)($body['phone']??''));$license=trim((string)($body['licenseNumber']??''));$status=$body['status']??'active';$address=trim((string)($body['address']??'')); if($name===''||$phone===''||$license==='')sendError('name, phone and licenseNumber are required.',422); if(!in_array($status,['active','inactive'],true))sendError('Invalid driver status.',422); if($method==='POST'){$st=$pdo->prepare('INSERT INTO drivers(name,phone,license_number,status,address) VALUES(:name,:phone,:license,:status,:address)');$st->execute(compact('name','phone','license','status','address'));$id=(int)$pdo->lastInsertId();} elseif(in_array($method,['PUT','PATCH'],true)&&$id){$st=$pdo->prepare('UPDATE drivers SET name=:name,phone=:phone,license_number=:license,status=:status,address=:address WHERE id=:id');$st->execute(compact('name','phone','license','status','address','id'));} else sendError('Invalid driver request.',400); $st=$pdo->prepare('SELECT id,name,phone,license_number AS licenseNumber,status,address,created_at AS createdAt,updated_at AS updatedAt FROM drivers WHERE id=:id');$st->execute(['id'=>$id]);sendResponse(['success'=>true,'data'=>$st->fetch()],$method==='POST'?201:200);
